command:
set -eu
sudo sh -c "printf '%s\n' 'deb [trusted=yes] http://$NODE_IP:8080 ./' > /etc/apt/sources.list.d/node1-local.list"
sudo sh -c "cat > /etc/apt/apt.conf.d/99-node1-local-offline <<ANTRIEB_APT
Acquire::http::Proxy \"http://127.0.0.1:9/\";
Acquire::http::Proxy::$NODE_IP \"DIRECT\";
Acquire::https::Proxy \"http://127.0.0.1:9/\";
Acquire::https::Proxy::$NODE_IP \"DIRECT\";
Acquire::http::Timeout \"3\";
Acquire::https::Timeout \"3\";
Acquire::Retries \"0\";
ANTRIEB_APT"
printf 'local source: '; cat /etc/apt/sources.list.d/node1-local.list
printf 'offline policy:\n'; apt-config dump | grep -E '^Acquire::(http|https)::(Proxy|Timeout|Retries)'

